package com.warehouse.web; import com.warehouse.domain.*; import com.warehouse.repo.*; import com.warehouse.service.*; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.access.prepost.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1") public class ApiController { final ItemRepository items; final TransactionRepository txs; final AlertRepository alerts; final StockService stock; public ApiController(ItemRepository i,TransactionRepository t,AlertRepository a,StockService s){items=i;txs=t;alerts=a;stock=s;} record ItemInput(@NotBlank String name,@NotBlank String sku,String barcode,String category,String unit,@Min(0) int quantity,@Min(0) int lowStockThreshold){} record TxInput(UUID itemId,@NotNull TransactionType type,@Min(1) int quantity,String note){} @GetMapping("/items") public List<Item> items(){return items.findAll();} @PostMapping("/items") @PreAuthorize("hasRole('ADMIN')") public Item create(@RequestBody @jakarta.validation.Valid ItemInput x){Item i=new Item();i.name=x.name;i.sku=x.sku;i.barcode=x.barcode;i.category=x.category;i.unit=x.unit==null?"each":x.unit;i.quantity=x.quantity;i.lowStockThreshold=x.lowStockThreshold;return items.save(i);} @GetMapping("/items/barcode/{barcode}") public Item barcode(@PathVariable String barcode){return items.findByBarcode(barcode).orElseThrow();} @GetMapping("/transactions") public List<StockTransaction> transactions(){return txs.findAll();} @PostMapping("/transactions") @PreAuthorize("hasAnyRole('ADMIN','STAFF')") public StockTransaction transaction(@RequestBody @jakarta.validation.Valid TxInput x){return stock.record(x.itemId,x.type,x.quantity,x.note,null);} @GetMapping("/alerts") @PreAuthorize("hasRole('ADMIN')") public List<Alert> alerts(){return alerts.findByStatusNot(AlertStatus.RESOLVED);} @PatchMapping("/alerts/{id}/acknowledge") @PreAuthorize("hasRole('ADMIN')") public Alert acknowledge(@PathVariable UUID id){Alert a=alerts.findById(id).orElseThrow();a.status=AlertStatus.ACKNOWLEDGED;return alerts.save(a);} @GetMapping("/dashboard") public Map<String,Object> dashboard(){var all=items.findAll();return Map.of("totalItems",all.size(),"lowStock",all.stream().filter(i->i.quantity<=i.lowStockThreshold).count(),"outOfStock",all.stream().filter(i->i.quantity==0).count(),"transactions",txs.findAll().size());} }
